        groups["dashboard"]=array(text("A · 数据分析仪表盘，全部为固定示例数据"),node("grid","核心指标","columns" to 2,"children" to array(node("stat","订单","value" to "69","unit" to "单"),node("stat","同比","value" to "+15","unit" to "%"))),chart("bar"),chart("line"),node("progress","月度目标","value" to 0.72),actions())
